const READ_LOGS_TIMEOUT_IN_MS = 30 * 1000;

// ANSI color/escape codes, e.g. "\x1B[0m"
const ANSI_COLOR_CODES = /\x1B\[[0-9;]*[A-Za-z]/g;
// Remaining control characters (including a lone Docker stream prefix / escape bytes)
// eslint-disable-next-line no-control-regex
const CONTROL_CHARACTERS = /[\x00-\x1F\x7F]/g;

const EZSP_PROTOCOL_VERSION_ERROR_PREFIX = 'Adapter EZSP protocol version';
const EZSP_PROTOCOL_VERSION_ERROR_SUFFIX = 'is not supported by Host';

const GENERIC_ERROR_REGEX = /error:/i;

/**
 * @description Read Zigbee2mqtt container logs and detect fatal errors.
 * @param {string} containerId - The Zigbee2mqtt container id.
 * @returns {Promise} Resolves once the logs have been analyzed.
 * @example
 * await this.readZ2mContainerLogs('container-id');
 */
async function readZ2mContainerLogs(containerId) {
  try {
    const logStream = await this.gladys.system.getContainerLogs(containerId, { follow: true });

    await new Promise((resolve) => {
      let resolved = false;
      let lastGenericErrorLine = null;
      let timeout;

      const finalize = (errorValue) => {
        if (resolved) {
          return;
        }
        resolved = true;
        clearTimeout(timeout);
        this.z2mContainerError = errorValue;
        resolve();
      };

      timeout = setTimeout(() => {
        finalize(lastGenericErrorLine ? { code: null, message: lastGenericErrorLine } : null);
      }, READ_LOGS_TIMEOUT_IN_MS);

      logStream.on('data', (chunk) => {
        const lines = chunk.toString().split('\n');
        lines.forEach((rawLine) => {
          // Strip the first character (Docker stream prefix byte)
          const withoutPrefix = rawLine.slice(1);
          // Strip ANSI color codes, then any remaining control characters
          const line = withoutPrefix.replace(ANSI_COLOR_CODES, '').replace(CONTROL_CHARACTERS, '');

          // Known error: EZSP protocol version not supported. Takes precedence.
          if (line.includes(EZSP_PROTOCOL_VERSION_ERROR_PREFIX) && line.includes(EZSP_PROTOCOL_VERSION_ERROR_SUFFIX)) {
            finalize({ code: 'EZSP_PROTOCOL_VERSION', message: null });
            logStream.destroy();
            return;
          }

          // Generic error: keep only the last matching line
          if (GENERIC_ERROR_REGEX.test(line)) {
            lastGenericErrorLine = line.trim();
          }
        });
      });

      logStream.on('error', () => {
        finalize(null);
      });

      logStream.on('end', () => {
        finalize(lastGenericErrorLine ? { code: null, message: lastGenericErrorLine } : null);
      });

      logStream.on('close', () => {
        finalize(lastGenericErrorLine ? { code: null, message: lastGenericErrorLine } : null);
      });
    });
  } catch (e) {
    logger.debug('Unable to read Zigbee2mqtt container logs:', e);
    this.z2mContainerError = null;
  }

  this.emitStatusEvent();
}

module.exports = {
  readZ2mContainerLogs,
};
